package com.onrender.smartnf.health;
import java.math.BigDecimal;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ShoppingProductService {
 public record Save(UUID listId,int entryNo,long listRevision,long expectedRevision,UUID requestId,String productId,String productName,String merchant,BigDecimal packGrams,BigDecimal price,int packs,String url,String checkedAt,boolean confirmed,String quantityUnit,BigDecimal requiredAmount,BigDecimal packageAmount,String optionName,boolean optionPriceConfirmed){
  public Save(UUID listId,int entryNo,long listRevision,long expectedRevision,UUID requestId,String productId,String productName,String merchant,BigDecimal packGrams,BigDecimal price,int packs,String url,String checkedAt,boolean confirmed,String quantityUnit,BigDecimal requiredAmount,BigDecimal packageAmount){this(listId,entryNo,listRevision,expectedRevision,requestId,productId,productName,merchant,packGrams,price,packs,url,checkedAt,confirmed,quantityUnit,requiredAmount,packageAmount,null,false);}
  public Save(UUID listId,int entryNo,long listRevision,long expectedRevision,UUID requestId,String productId,String productName,String merchant,BigDecimal packGrams,BigDecimal price,int packs,String url,String checkedAt,boolean confirmed){this(listId,entryNo,listRevision,expectedRevision,requestId,productId,productName,merchant,packGrams,price,packs,url,checkedAt,confirmed,"g",null,packGrams);}
 }
 public record Choice(UUID listId,int entryNo,long revision,long listRevision,String ingredientName,BigDecimal requiredGrams,String productId,String productName,String merchant,BigDecimal packGrams,BigDecimal price,int packs,String url,String checkedAt,boolean stale,String sourceDetails,String quantityUnit,BigDecimal requiredAmount,BigDecimal packageAmount){}
 private final JdbcTemplate jdbc;private final ShoppingListService lists;public ShoppingProductService(JdbcTemplate jdbc,ShoppingListService lists){this.jdbc=jdbc;this.lists=lists;}
 private static String text(String s,int max){if(s==null||s.isBlank()||s.length()>max||s.chars().anyMatch(Character::isISOControl))throw HealthException.invalid();return s.strip();}
 public static Save validate(Save s){if(s==null||s.listId()==null||s.requestId()==null||s.entryNo()<0||s.entryNo()>999||s.listRevision()<1||s.expectedRevision()<0||s.expectedRevision()==Long.MAX_VALUE||!s.confirmed()||s.packs()<1||s.packs()>100000)throw HealthException.invalid();
  String unit=s.quantityUnit()==null?"g":s.quantityUnit();BigDecimal pack=s.packageAmount()==null?s.packGrams():s.packageAmount();
  if(!Set.of("g","ml","ea","pack","bag","bottle").contains(unit)||pack==null||pack.signum()<=0||pack.compareTo(new BigDecimal("10000000"))>0||pack.stripTrailingZeros().scale()>3)throw HealthException.invalid();
  if(!Set.of("g","ml").contains(unit)&&pack.stripTrailingZeros().scale()>0)throw new HealthException(400,"판매포장의 개수·팩·봉·병 수는 정수로 확인하세요.");
  if(!unit.equals("g")&&(s.requiredAmount()==null||s.requiredAmount().signum()<=0||s.requiredAmount().compareTo(new BigDecimal("10000000"))>0||s.requiredAmount().stripTrailingZeros().scale()>3))throw HealthException.invalid();
  if(s.price()==null||s.price().signum()<=0||s.price().compareTo(new BigDecimal("100000000"))>0||s.price().stripTrailingZeros().scale()>2)throw HealthException.invalid();
  String id=text(s.productId(),50),url=text(s.url(),2000);if(!(id.matches("[0-9]{1,30}")&&url.equals("https://www.11st.co.kr/products/"+id))&&!(id.matches("c:[a-f0-9-]{36}")&&CollectedProductService.officialUrl(url))&&!(id.matches("k:[a-f0-9-]{36}")&&KakaoProductSnapshots.validAnyLiveUrl(url)))throw HealthException.invalid();try{Instant.parse(s.checkedAt());}catch(Exception e){throw HealthException.invalid();}
  if(s.optionPriceConfirmed()&&(!s.productId().startsWith("k:")||!unit.equals("g")||pack.compareTo(new BigDecimal("1000"))!=0))throw HealthException.invalid();
  if(s.optionPriceConfirmed())text(s.optionName(),100);
  if(!s.optionPriceConfirmed()&&s.optionName()!=null&&!s.optionName().isBlank())throw HealthException.invalid();
  return new Save(s.listId(),s.entryNo(),s.listRevision(),s.expectedRevision(),s.requestId(),id,text(s.productName(),300),text(s.merchant(),300),unit.equals("g")?pack.stripTrailingZeros():null,s.price().stripTrailingZeros(),s.packs(),url,s.checkedAt(),true,unit,s.requiredAmount(),pack.stripTrailingZeros(),s.optionPriceConfirmed()?s.optionName().strip():null,s.optionPriceConfirmed());
 }
 private List<Choice> read(long member,UUID id,long currentRevision){return jdbc.query("SELECT c.* FROM shopping_product_choices c JOIN shopping_lists l ON l.id=c.list_id WHERE l.member_id=? AND l.deleted=FALSE AND c.list_id=? ORDER BY c.entry_no",(x,n)->new Choice(id,x.getInt("entry_no"),x.getLong("revision"),x.getLong("list_revision"),x.getString("ingredient_name"),x.getBigDecimal("required_grams"),x.getString("product_id"),x.getString("product_name"),x.getString("merchant"),x.getBigDecimal("pack_grams"),x.getBigDecimal("unit_price"),x.getInt("pack_count"),x.getString("product_url"),x.getString("checked_at"),x.getLong("list_revision")!=currentRevision,x.getString("source_details"),x.getString("quantity_unit"),x.getBigDecimal("required_amount"),x.getBigDecimal("package_amount")),member,id.toString());}
 @Transactional(readOnly=true) public List<Choice> get(long member,UUID id){var list=lists.get(member,id);return read(member,id,list.revision());}
 @Transactional public Choice save(long member,Save raw){Save s=validate(raw);if(jdbc.queryForList("SELECT id FROM members WHERE id=? FOR UPDATE",Long.class,member).isEmpty())throw new HealthException(403,"회원 상태를 확인하세요.");var list=lists.get(member,s.listId());
  String sourceDetails="API · 11ST · ONLINE · 배송비·옵션·회원 조건 별도 확인";
  if(s.productId().startsWith("c:")){
   if(!s.quantityUnit().equals("g"))throw HealthException.invalid();
   String day=LocalDate.now(ZoneId.of("Asia/Seoul")).toString();
   var rows=jdbc.queryForList("SELECT * FROM collected_product_offers WHERE member_id=? AND id=? AND valid_from<=? AND valid_to>=?",member,s.productId().substring(2),day,day);
   if(rows.isEmpty())throw new HealthException(409,"수집 상품이 만료되거나 변경됐습니다. 다시 조회하세요.");var row=rows.getFirst();
   sourceDetails=String.join(" · ",String.valueOf(row.get("source_type")),String.valueOf(row.get("provider")),String.valueOf(row.get("price_kind")),String.valueOf(row.get("branch")),row.get("valid_from")+" ~ "+row.get("valid_to"),String.valueOf(row.get("conditions_text")));
   if(!s.productName().equals(row.get("product_name"))||!s.url().equals(row.get("product_url"))||!s.merchant().equals(row.get("merchant"))||!s.checkedAt().equals(row.get("checked_at"))||s.price().compareTo((BigDecimal)row.get("unit_price"))!=0||s.packGrams().compareTo((BigDecimal)row.get("pack_grams"))!=0)throw HealthException.conflict();
  }
  String hash;try{hash=HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(s.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}
  var old=read(member,s.listId(),list.revision()).stream().filter(c->c.entryNo()==s.entryNo()).findFirst().orElse(null);
  if(old!=null){var previous=jdbc.queryForMap("SELECT last_request_id,last_request_hash FROM shopping_product_choices WHERE list_id=? AND entry_no=?",s.listId().toString(),s.entryNo());if(s.requestId().toString().equals(previous.get("last_request_id"))){if(!hash.equals(previous.get("last_request_hash")))throw HealthException.conflict();return old;}}
  if(s.productId().startsWith("k:")){var p=KakaoProductSnapshots.require(member,s);sourceDetails=(s.optionPriceConfirmed()?"사용자 확인 옵션 · "+s.optionName()+" · 대표 규격 1kg · 옵션 가격 "+s.price()+"원 · 검색 대표가격 "+p.price()+"원 · ":"")+"사용자 선택 · "+p.provider()+" · 판매 표시가(쿠폰·카드·옵션 가능) · "+p.conditions()+" · 배송: "+p.delivery()+" · 최종 결제금액 아님";}
  if(list.revision()!=s.listRevision()||s.entryNo()>=list.items().size()||(old==null?0:old.revision())!=s.expectedRevision())throw HealthException.conflict();
  var ingredient=list.items().get(s.entryNo());if(s.quantityUnit().equals("g")&&s.requiredAmount()!=null&&(ingredient.grams()==null||s.requiredAmount().compareTo(ingredient.grams())!=0))throw HealthException.invalid();BigDecimal known=ShoppingListModels.required(ingredient,s.quantityUnit());if(known!=null&&s.requiredAmount()!=null&&known.compareTo(s.requiredAmount())!=0)throw new HealthException(400,"저장된 장보기 필요량과 다릅니다. 목록에서 먼저 수정하세요.");long next=s.expectedRevision()+1;
  if(old==null)jdbc.update("INSERT INTO shopping_product_choices(list_id,entry_no,revision,list_revision,ingredient_name,required_grams,product_id,product_name,merchant,pack_grams,unit_price,pack_count,product_url,checked_at,last_request_id,last_request_hash,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",s.listId().toString(),s.entryNo(),next,s.listRevision(),ingredient.name(),ingredient.grams(),s.productId(),s.productName(),s.merchant(),s.packGrams(),s.price(),s.packs(),s.url(),s.checkedAt(),s.requestId().toString(),hash,LocalDateTime.now(ZoneOffset.UTC));
  else jdbc.update("UPDATE shopping_product_choices SET revision=?,list_revision=?,ingredient_name=?,required_grams=?,product_id=?,product_name=?,merchant=?,pack_grams=?,unit_price=?,pack_count=?,product_url=?,checked_at=?,last_request_id=?,last_request_hash=?,updated_at=? WHERE list_id=? AND entry_no=?",next,s.listRevision(),ingredient.name(),ingredient.grams(),s.productId(),s.productName(),s.merchant(),s.packGrams(),s.price(),s.packs(),s.url(),s.checkedAt(),s.requestId().toString(),hash,LocalDateTime.now(ZoneOffset.UTC),s.listId().toString(),s.entryNo());
  jdbc.update("UPDATE shopping_product_choices SET source_details=? WHERE list_id=? AND entry_no=?",sourceDetails,s.listId().toString(),s.entryNo());
  jdbc.update("UPDATE shopping_product_choices SET quantity_unit=?,required_amount=?,package_amount=? WHERE list_id=? AND entry_no=?",s.quantityUnit(),s.quantityUnit().equals("g")?ingredient.grams():s.requiredAmount(),s.packageAmount(),s.listId().toString(),s.entryNo());
  return read(member,s.listId(),list.revision()).stream().filter(c->c.entryNo()==s.entryNo()).findFirst().orElseThrow();
 }
}
